-- 레거시 미니펫 전체 객체와 확률 기반 동적 카탈로그를 비활성 상태로 이관합니다.
-- miniPet 1,078개는 모두 item_definitions에 저장합니다.
-- gradeTable에 없는 엘리트 12개는 임의 확률을 만들지 않고 dynamic_item_catalog_entries에서 제외합니다.
-- 레거시 데이터에는 같은 name + MINI_PET 조합이 있으므로 uq_item_definition_name_type을 의도적으로 제거합니다.
-- item_id 기본키와 dynamic_item_catalog_entries 기본키로 재실행 안전성을 유지합니다.

SET NAMES utf8mb4;
START TRANSACTION;

SET @drop_legacy_mini_pet_name_type_uq = (
  SELECT IF(
    COUNT(*) > 0,
    'ALTER TABLE `item_definitions` DROP INDEX `uq_item_definition_name_type`',
    'SELECT 1'
  )
  FROM information_schema.statistics
  WHERE table_schema = DATABASE()
    AND table_name = 'item_definitions'
    AND index_name = 'uq_item_definition_name_type'
);
PREPARE drop_legacy_mini_pet_name_type_uq_stmt FROM @drop_legacy_mini_pet_name_type_uq;
EXECUTE drop_legacy_mini_pet_name_type_uq_stmt;
DEALLOCATE PREPARE drop_legacy_mini_pet_name_type_uq_stmt;

ALTER TABLE item_definitions
  MODIFY stackable TINYINT(1) NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS ix_item_definition_name_type
  ON item_definitions(item_name, item_type);

ON DUPLICATE KEY UPDATE
  item_type = VALUES(item_type),
  item_name = VALUES(item_name),
  metadata_json = VALUES(metadata_json),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  item_type = VALUES(item_type),
  item_name = VALUES(item_name),
  metadata_json = VALUES(metadata_json),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  item_type = VALUES(item_type),
  item_name = VALUES(item_name),
  metadata_json = VALUES(metadata_json),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  item_type = VALUES(item_type),
  item_name = VALUES(item_name),
  metadata_json = VALUES(metadata_json),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  item_type = VALUES(item_type),
  item_name = VALUES(item_name),
  metadata_json = VALUES(metadata_json),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  item_type = VALUES(item_type),
  item_name = VALUES(item_name),
  metadata_json = VALUES(metadata_json),
  enabled = VALUES(enabled);

-- 이전 실행이나 수동 입력으로 생겼을 수 있는 비대상 엘리트 카탈로그 행을 제거합니다.
DELETE FROM dynamic_item_catalog_entries
WHERE catalog_code = 'legacy-mini-pet'
  AND item_id IN (
    'ITEM-MINIPET-CATALOG-1067',
    'ITEM-MINIPET-CATALOG-1068',
    'ITEM-MINIPET-CATALOG-1069',
    'ITEM-MINIPET-CATALOG-1070',
    'ITEM-MINIPET-CATALOG-1071',
    'ITEM-MINIPET-CATALOG-1072',
    'ITEM-MINIPET-CATALOG-1073',
    'ITEM-MINIPET-CATALOG-1074',
    'ITEM-MINIPET-CATALOG-1075',
    'ITEM-MINIPET-CATALOG-1076',
    'ITEM-MINIPET-CATALOG-1077',
    'ITEM-MINIPET-CATALOG-1078'
  );

ON DUPLICATE KEY UPDATE
  grade_code = VALUES(grade_code),
  grade_weight = VALUES(grade_weight),
  item_weight = VALUES(item_weight),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  grade_code = VALUES(grade_code),
  grade_weight = VALUES(grade_weight),
  item_weight = VALUES(item_weight),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  grade_code = VALUES(grade_code),
  grade_weight = VALUES(grade_weight),
  item_weight = VALUES(item_weight),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  grade_code = VALUES(grade_code),
  grade_weight = VALUES(grade_weight),
  item_weight = VALUES(item_weight),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  grade_code = VALUES(grade_code),
  grade_weight = VALUES(grade_weight),
  item_weight = VALUES(item_weight),
  enabled = VALUES(enabled);

ON DUPLICATE KEY UPDATE
  grade_code = VALUES(grade_code),
  grade_weight = VALUES(grade_weight),
  item_weight = VALUES(item_weight),
  enabled = VALUES(enabled);

UPDATE package_reward_rules
SET selector_json = '{"itemType":"MINI_PET","catalogCode":"legacy-mini-pet","respectCapacity":true,"consumeOnlyGranted":true}'
WHERE rule_id = 'RULE-PKG-105-001';

UPDATE package_catalog
SET max_open_count = 3000,
    enabled = 0
WHERE package_id = 'PKG-105';

COMMIT;
